Here are several implementations of a factorial function in TypeScript:

## 1. Iterative Approach (Recommended)

```typescript
function factorial(n: number): number {
  // Input validation
  if (n < 0) {
    throw new Error("Factorial is not defined for negative numbers");
  }

  if (!Number.isInteger(n)) {
    throw new Error("Factorial is only defined for integers");
  }

  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }

  return result;
}
```

## 2. Recursive Approach

```typescript
function factorialRecursive(n: number): number {
  // Input validation
  if (n < 0) {
    throw new Error("Factorial is not defined for negative numbers");
  }

  if (!Number.isInteger(n)) {
    throw new Error("Factorial is only defined for integers");
  }

  // Base cases
  if (n === 0 || n === 1) {
    return 1;
  }

  // Recursive case
  return n * factorialRecursive(n - 1);
}
```

## 3. Using BigInt for Large Numbers

```typescript
function factorialBigInt(n: number): bigint {
  // Input validation
  if (n < 0) {
    throw new Error("Factorial is not defined for negative numbers");
  }

  if (!Number.isInteger(n)) {
    throw new Error("Factorial is only defined for integers");
  }

  let result = 1n;
  for (let i = 2n; i <= BigInt(n); i++) {
    result *= i;
  }

  return result;
}
```

## 4. Memoized Recursive Approach

```typescript
function factorialMemoized(): (n: number) => number {
  const cache: Map<number, number> = new Map();

  function factorial(n: number): number {
    // Input validation
    if (n < 0) {
      throw new Error("Factorial is not defined for negative numbers");
    }

    if (!Number.isInteger(n)) {
      throw new Error("Factorial is only defined for integers");
    }

    // Check cache
    if (cache.has(n)) {
      return cache.get(n)!;
    }

    // Base cases
    if (n === 0 || n === 1) {
      cache.set(n, 1);
      return 1;
    }

    // Calculate and cache result
    const result = n * factorial(n - 1);
    cache.set(n, result);
    return result;
  }

  return factorial;
}

// Usage
const factorial = factorialMemoized();
```

