function factorialOptimized(n: number): number {
  if (n < 0) {
    throw new RangeError("Factorial is not defined for negative numbers.");
  }

  // Early exit for the base cases
  if (n <= 1) {
    return 1;
  }

  // Use a let variable for better performance in the loop
  let result = 1n; // Use BigInt for large numbers to avoid integer overflow
  for (let i = 2n; i <= n; i++) {
    result *= i;
  }
  return Number(result); // Convert back to number for the return type
}

// --- Example Usage ---

